package com.aac.ieojwo.alert.domain;
import com.aac.ieojwo.common.domain.BaseTimeEntity;import com.aac.ieojwo.guardian.domain.Guardian;import jakarta.persistence.*;
@Entity @Table(name="notification_subscriptions",uniqueConstraints=@UniqueConstraint(name="uk_subscription_endpoint",columnNames="endpoint"))
public class NotificationSubscription extends BaseTimeEntity{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="guardian_id",nullable=false)private Guardian guardian;@Column(nullable=false,length=1000)private String endpoint;@Column(nullable=false,length=300)private String p256dh;@Column(name="auth_key",nullable=false,length=300)private String authKey;@Column(nullable=false)private boolean active;protected NotificationSubscription(){}public static NotificationSubscription create(Guardian g,String e,String p,String a){NotificationSubscription s=new NotificationSubscription();s.guardian=g;s.endpoint=e;s.p256dh=p;s.authKey=a;s.active=true;return s;}public void update(Guardian g,String p,String a){guardian=g;p256dh=p;authKey=a;active=true;}public void disable(){active=false;}public Long getId(){return id;}public String getEndpoint(){return endpoint;}public boolean isActive(){return active;}}
